require_once __DIR__ . '/../includes/table_admin.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('database/index.php');$table=posted('table');require_csrf_or_redirect('database/structure.php?table='.urlencode($table));$column=posted('column');$columns=valid_table_name($table)?all_rows('DESCRIBE '.quoted_identifier($table)):[];$match=null;foreach($columns as $item){if($item['Field']===$column)$match=$item;}if(!posted('confirm')||!$match||$match['Key']==='PRI'){set_flash('danger','A valid, confirmed non-primary-key column deletion is required.');redirect('database/structure.php?table='.urlencode($table));}try{db()->exec('ALTER TABLE '.quoted_identifier($table).' DROP COLUMN '.quoted_identifier($column));set_flash('success','Column '.$column.' was removed.');}catch(PDOException $exception){set_flash('danger','The column could not be removed because it is required by a database constraint.');}redirect('database/structure.php?table='.urlencode($table));
